import {ToolRegistry} from './registry.js';
import type {ToolDefinition} from '../../types/ai.js';

describe('ToolRegistry', () => {
  it('compiles a static inputSchema once at register time without re-reading it on execute', async () => {

  it('caches compiled validators for function-valued definitions by schema object reference', async () => {
    const registry = new ToolRegistry();
    const cityTracker = trackSchemaCompilation('city');
    const zipTracker = trackSchemaCompilation('zip');
    let activeSchema = cityTracker.schema;

    registry.register(
      () => ({
        name: 'dynamic_weather',
        description: 'Get weather',
        inputSchema: activeSchema,
      }),
      async input => JSON.stringify(input)
    );

    const readsAtRegister = cityTracker.reads();
    await registry.execute('dynamic_weather', {city: 'Oslo'});
    const readsAfterFirstCity = cityTracker.reads();
    await registry.execute('dynamic_weather', {city: 'Bergen'});
    const readsAfterSecondCity = cityTracker.reads();
    activeSchema = zipTracker.schema;
    await registry.execute('dynamic_weather', {zip: '0150'});
    const readsAfterZip = zipTracker.reads();
    activeSchema = cityTracker.schema;
    await registry.execute('dynamic_weather', {city: 'Trondheim'});
    const readsAfterReturnToCity = cityTracker.reads();

    expect({
      readsAtRegister,
      compiledOnFirstUse: readsAfterFirstCity > 0,
      reusedSameReference: readsAfterSecondCity === readsAfterFirstCity,
      compiledNewReference: readsAfterZip > 0,
      retainedFirstReference: readsAfterReturnToCity === readsAfterFirstCity,
    }).toEqual({
      readsAtRegister: 0,
      compiledOnFirstUse: true,
      reusedSameReference: true,
      compiledNewReference: true,
      retainedFirstReference: true,
    });
  });
});

