  it('caches compiled validators for function-valued definitions by schema object reference', async () => {
    const registry = new ToolRegistry();
    const cityTracker = trackSchemaCompilation('city');
    let activeSchema = cityTracker.schema;

    registry.register(
      () => ({
        name: 'dynamic_weather',
        description: 'Get weather',
        inputSchema: activeSchema,
      }),
      async input => JSON.stringify(input)
    );

    const observations: Record<string, number | boolean> = {
      readsAtRegister: cityTracker.reads(),
    };
    await registry.execute('dynamic_weather', {city: 'Oslo'});
    const readsAfterFirstCity = cityTracker.reads();
    observations.compiledOnFirstUse = readsAfterFirstCity > 0;
    await registry.execute('dynamic_weather', {city: 'Bergen'});
    observations.reusedSameReference = cityTracker.reads() === readsAfterFirstCity;
    const zipTracker = trackSchemaCompilation('zip');
    activeSchema = zipTracker.schema;
    await registry.execute('dynamic_weather', {zip: '0150'});
    observations.compiledNewReference = zipTracker.reads() > 0;
    activeSchema = cityTracker.schema;
    await registry.execute('dynamic_weather', {city: 'Trondheim'});
    observations.retainedFirstReference = cityTracker.reads() === readsAfterFirstCity;

    expect(observations).toEqual({
      readsAtRegister: 0,
      compiledOnFirstUse: true,
      reusedSameReference: true,
      compiledNewReference: true,
      retainedFirstReference: true,
    });
  });

  it('rejects enum, nested required, and type failures without calling the executor or leaking values', async () => {
    const recordedLogs: string[] = [];
    const recordLine = (category: string, message: string, fields?: Record<string, unknown>) => {
      recordedLogs.push(JSON.stringify({category, message, fields}));
    };
    const logger: Logger = {
      debug: recordLine,
      info: recordLine,
      warn: recordLine,
      error: recordLine,
    };
    setLogger(logger);

    const registry = new ToolRegistry();
    let executorCalls = 0;
    registry.register(
      {
        name: 'create_booking',
        description: 'Create a booking',
        inputSchema: {
          type: 'object',
          properties: {
            seats: {type: 'number'},
            cabin: {type: 'string', enum: ['economy', 'business']},
            passenger: {
              type: 'object',
              properties: {passport: {type: 'string'}},
              required: ['passport'],
            },
          },
          required: ['seats', 'cabin', 'passenger'],
        },
      },
      async () => {
        executorCalls += 1;
        return 'booked';
      }
    );

    const response = await registry.execute('create_booking', {
      seats: '42',
      cabin: 'secret-first-class',
      passenger: {},
    });

    expect({
      executorCalls,
      mentionsSeatsNumber: response.result.includes('seats') && response.result.includes('number'),
      mentionsCabinEnum: response.result.includes('cabin') && response.result.includes('economy'),
      mentionsNestedPassport:
        response.result.includes('passenger.passport') && /required/i.test(response.result),
      leaksValueInResult:
        response.result.includes('secret-first-class') || response.result.includes('42'),
      leaksValueInLogs: recordedLogs.some(
        line => line.includes('secret-first-class') || line.includes('42')
      ),
    }).toEqual({
      executorCalls: 0,
      mentionsSeatsNumber: true,
      mentionsCabinEnum: true,
      mentionsNestedPassport: true,
      leaksValueInResult: false,
      leaksValueInLogs: false,
    });
  });
});

