/** Validates input against the tool's schema (returns a ToolResponse on failure, throws only on unknown tool); see specs/hal-engine-tool-input-validation/spec.md. */
async execute(name: string, input: Record<string, unknown>, context?: ToolContext): Promise<ToolResponse> {
  const tool = this.tools.get(name);
  if (!tool) {
    log.warn('tool', 'tool not found', {name});
    throw new Error(`Unknown tool: ${name}`);
  }
  const validator = this.resolveValidator(tool);
  if (!validator(input)) {
    const reasons = formatValidationErrors(validator.errors);
    log.warn('tool', 'validation failed', {name, reasons});
    return {result: `Invalid input for tool "${name}": ${reasons.join('; ')}`};
  }
  log.info('tool', 'executing', {name, inputKeys: Object.keys(input)});

