function compileSchema(
  compiler: InstanceType<typeof Ajv>,
  toolName: string,
  schema: Record<string, unknown>
): ValidateFunction {
  try {
    return compiler.compile(schema);
  } catch (error) {
    const reason = error instanceof Error ? error.message : String(error);
    throw new Error(`Tool "${toolName}" has an uncompilable inputSchema: ${reason}`, {cause: error});
  }
}

