function compileSchema(
  compiler: InstanceType<typeof Ajv>,
  toolName: string,
  schema: Record<string, unknown>
): ValidateFunction {
  try {
    return compiler.compile(schema);
  } catch (error) {
    const reason = error instanceof Error ? error.message : String(error);
    throw new Error(`Tool "${toolName}" has an uncompilable inputSchema: ${reason}`, {cause: error});
  }
}

function formatValidationErrors(errors: ErrorObject[] | null | undefined): string[] {
  if (!errors || errors.length === 0) {
    return ['input did not match schema'];
  }
  return errors.map(formatValidationError);
}

function formatValidationError(error: ErrorObject): string {
  const basePath = error.dataPath.replace(/^\./, '');
  if (error.keyword === 'required') {
    const missing = (error.params as {missingProperty?: unknown}).missingProperty;
    const field =
      typeof missing === 'string' && missing ? [basePath, missing].filter(Boolean).join('.') : basePath || 'input';
    return `${field}: missing required property`;
  }
  const field = basePath || 'input';
  const description = error.message ?? error.keyword;
  if (error.keyword === 'enum') {
    const allowed = (error.params as {allowedValues?: unknown}).allowedValues;
    const choices = Array.isArray(allowed) ? allowed.map(choice => String(choice)).join(', ') : '';
    return choices ? `${field}: ${description} (${choices})` : `${field}: ${description}`;
  }
  return `${field}: ${description}`;
}

